"""Render the Russian research note after locked scoring."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
load=lambda n:json.loads((ROOT/n).read_bytes())
f=lambda n:f'{n:.3f}'.replace('.',',')
precise=lambda n:f'{n:.5f}'.rstrip('0').rstrip('.').replace('.',',') if n else '0'
diff=lambda v:f"{precise(v['delta'])} [{precise(v['ci'][0])}; {precise(v['ci'][1])}]"
r=load('results.json'); cpu=load('cpu_summary.json'); profile=load('cpu_profile.json');audit=load('previous_message_audit.json'); distance=load('control_distance.json')
arms=r['arms'];pairs=r['pair'];cache=r['cache'];primary=pairs['correction-control']
names={'baseline':'Исходный Concord','correction':'Исправленный фрагмент','control':'Неизменившийся фрагмент'}
lines=['# Что даёт выделение правки в уже показанном источнике', '',
       f"На 40 вопросах ConcordBench новая ветвь с выделением исправленного текста дала {arms['correction']['em']}/40 точных ответов и средний token F1 {f(arms['correction']['f1'])}. Сопоставимое уведомление с неизменившимся текстом дало {arms['control']['em']}/40 и {f(arms['control']['f1'])}. Основной парный контраст по EM составил {diff(primary['em'])}, по F1 — {diff(primary['f1'])}. Нулевой эффект остаётся совместим с обоими интервалами. Исходный Concord также дал 8/40 точных ответов.", '',
       '## Как выбирали вмешательство','',
       'Это дополнительная разведочная проверка после известного нулевого срабатывания предыдущего расширения и после просмотра его качества. До новой генерации зафиксировали минимальную правку, контроль, порядок выбора одного правила и пределы длины. Воспроизвели на CPU все 197 обращений исходного Concord на 40 задачах. Каждая полезная нагрузка HTTP побайтно совпала с исходной после канонической сериализации JSON. Выбор правила зависел от частоты наблюдаемого события. Финальные ответы, разметка, вопрос, запланированные изменения и другие будущие события не поступали селектору.', '',
       'В 31/40 траекториях ранее показанный валидный фрагмент grep/read_file изменился в следующем доступном представлении того же сообщения. В 21 задаче можно было выдать одну подсказку, в 10 — две, в 9 — ни одной. Из 62 допустимых изменений отобрали 41 уведомление, максимум одно за обращение. Подсчёт по сырым HTTP-сообщениям подтвердил каждую фактическую замену. В 16 из 41 случая новая строка уже встречалась как подстрока в другой позиции либо части старого текста. Уведомление сообщает об изменении позиции, степень новизны для модели зависит от задачи. Запасное правило от момента возврата инструментом дало 43 возможности в 32/40 задачах и в новых генерациях не применялось.', '',
       'История Concord сохраняется целиком. Обе ветви добавляют одинаковый префикс, адрес документа и короткий фрагмент текущего валидного текста. Префикс дописывается к штатному уведомлению, если оно есть, иначе добавляется отдельное сообщение с ролью user. Исправленная ветвь повторяет первый изменённый фрагмент, до 16 слов и 120 байт. Контроль берёт фрагмент из неизменившейся части той же записи, минимизируя расхождение числа слов и байтов и пересечение с исправлением. При одновременных изменениях выбирается последнее сообщение и последний подходящий блок. Ключ дедупликации включает ID возврата, позицию блока и хеш его нового текста. Кандидаты одного шага помечаются обработанными. Один и тот же факт в новом возврате инструмента может вновь стать кандидатом.', '',
       'В каждой ветви Qwen3.8-27B UD-Q4_K_M обращается к тому же локальному серверу и циклу официальных инструментов. Декодирование детерминированное, максимум 256 выходных токенов за запрос, до 30 событий, один исполняемый инструмент за событие. Очередность двух ветвей менялась детерминированно по задаче. Решения по всем 80 новым траекториям заблокированы до оценки.', '',
       '## Качество и стоимость по всем вопросам','',
       '| Ветвь | EM | F1 | Вопросы с подсказкой | Подсказки | grep | read_file | Запросы модели | Входные токены | Выходные токены |',
       '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for a in ('baseline','correction','control'):
    v=arms[a]
    lines.append(f"| {names[a]} | {v['em']}/40 | {f(v['f1'])} | {v['cue_cases']}/40 | {v['cues']} | {v['grep']} | {v['read_file']} | {v['request_count']} | {v['prompt']} | {v['completion']} |")
lines+=['','| Парная разность | Δ EM [95% ДИ] | Победы/поражения по EM | Двусторонний p знаков | Δ F1 [95% ДИ] | Победы/поражения по F1 |',
        '|---|---:|---:|---:|---:|---:|']
for name,p in pairs.items():
    a,b=name.split('-');em=p['em'];f1=p['f1']
    lines.append(f"| {names[a]} минус {names[b]} | {diff(em)} | {em['wins']}/{em['losses']} | {f(em['exact_sign_p'])} | {diff(f1)} | {f1['wins']}/{f1['losses']} |")
first=primary['first_intervention_prompt_token_difference']
lines+=['',
        'Все оценки в таблице включают и задачи, на которых правило ни разу не сработало. Качество выражено долей точных ответов и средним токенным F1 по официальной нормализации. ДИ получены 10 000 повторными парными выборками целых задач, seed 20261118. Тест знаков исключает ничьи. Интервалы описательные, без коррекции за множественность. Отложенной независимой выборки для этой новой гипотезы нет.', '',
        f"Впервые две подсказки были предъявлены на строго одинаковом входе для {primary['same_first_event']} задачи. Удаление каждой из них восстановило исходный SHA-256 stock-запроса. По сравнению с исходным запросом исправление добавило в среднем {f(first['correction-baseline']['delta'])} токена, контроль — {f(first['control-baseline']['delta'])}. Разность по этим первым сопоставимым решениям составила {diff(first['correction-control'])} токена, диапазон от {first['correction-control']['min_tokens']} до {first['correction-control']['max_tokens']}. На дальнейших шагах изменение решения модели могло поменять поиск, длину контекста и набор событий. Полные последовательности запросов совпали у ветвей в {primary['same_request_sequence']}/40, полные последовательности отобранных событий — в {primary['same_event_sequence']}/40, финальные строки ответов разошлись в {primary['different_answer']}/40.",'']
lines += [f"CPU-проверка соседства на всех 41 исходных событиях дала медиану {distance['median_gap_words']} слова между исправлением и выбранным контрольным фрагментом. В {distance['within20']}/41 разрыв был не более 20 слов, максимум {distance['max_gap_words']}. Оба фрагмента находились в одном блоке.",'']
direct=primary['descriptive_first_model_action']
lines += [f"Сразу после первого предъявления для {primary['same_first_event']} задачи модель попыталась вызвать инструмент окончательного ответа {direct['correction']['attempted_answer']} раз с исправленным фрагментом, {direct['control']['attempted_answer']} раз с неизменившимся и {direct['baseline']['attempted_answer']} раз в исходном Concord. По сравнению двух новых ветвей последовательность имён запрошенных инструментов различалась в {direct['primary_different_names']} ситуациях, выбор с учётом аргументов — в {direct['primary_different_name_or_arguments']}. Это дополнительное описание первой реакции модели. Некоторые попытки ответа мог перехватить штатный цикл.",'']
for a in ('correction','control'):
    v=arms[a]
    lines.append(f"Ветвь «{names[a].lower()}» вывела {v['cue_bytes']} байт уведомлений с локаторами, из них {v['phrase_bytes']} байт, или {v['phrase_words']} слов, относятся к фрагментам. Точное совпадение количества слов двух кандидатов до выбора ветви было в {v['same_word_length']}/{v['cues']} случаях. Общих уведомлений-заглушек было {v['generic_control']}. Фактически предъявлено событий {v['cues']}, подходящих изменений до ограничения по одному за шаг — {v['eligible']}.")
    lines.append('')
lines +=[f"На две новые ветви суммарно пришлось {cache['extension_logical']} логических запросов и {cache['distinct_extension_keys']} уникальных полных запросов. Ранее измеренные ответы покрыли {cache['old_unique_receipts']} уникальных ключей. В дополнительном опыте потребовалось {cache['new_unique_receipts']} новых обращений к модели, {cache['new_physical_prompt']} фактических входных и {cache['new_physical_completion']} выходных токенов по этим выдачам. Повторов внутри одной траектории было {cache['repeated_within_trajectory']}, дополнительное межветвевое совпадение в той же задаче — {cache['across_arms_in_same_case']}. Ошибок HTTP и пропавших квитанций — {cache['errors']} и {sum(arms[a]['missing_receipts'] for a in ('correction','control'))}. Токены отдельного судьи в эти итоги не входят.",'',
          f"Селектор извлекает уже материализованный фрагмент из памяти и выполняет ноль дополнительных чтений файла. Обычные действия агента, включая read_file, приведены в таблице. Один дополнительный CPU-проход на исходных 197 шагах дал медиану добавочного времени {profile['additional_selection_and_format']['median_us']:.1f} мкс, 95-й перцентиль {profile['additional_selection_and_format']['p95_us']:.1f} мкс. На 41 шаге с событием медиана составила {profile['on_event']['median_us']:.1f} мкс. Это замер селекции и формирования строки на данной машине при параллельной загрузке, без вызова модели и файлового ввода-вывода.",'',
          'Стандартные ответы, локальная слепая оценка и оценки опубликованных моделей имеют разные источники. Для независимого прохода тем же локальным судьёй передан файл answers_for_judge.json, содержащий ровно 80 строк с идентификатором, методом и заблокированным ответом. Отдельный судейский процесс убирает признаки метода перед запросом. Числа в настоящих таблицах получены механическим подсчётом.', '',
          'Один локальный квантованный читатель, 40 ранее наблюдавшихся HotpotQA-вопросов и искусственно запланированные замены источников ограничивают перенос. Действия агента вызывают часть замен, поэтому покрытие и траектории могут зависеть от вмешательства. Контроль сам предъявляет правдивый фрагмент и может помочь ответить. Обоснование превосходства над открытыми моделями или официальным судейским рейтингом потребовало бы самостоятельных задач, нескольких читателей и сопоставимого оценивания.', '',
          'Код источника и официальная статья доступны по ссылкам. [Репозиторий Concord на использованной ревизии](https://github.com/FFFFFFFANG1/Concord/tree/4116936349995f0f30597931c0dbbebcbf7e58ac) · [Публикация ConcordBench](https://arxiv.org/abs/2610.05281).',
          '', 'В каталоге находятся предварительный протокол, design_lock.json, CPU-аудит, полные решения и их decision_lock.json, пообъектная projection.json.gz, попарные results.json и независимый проверочный скрипт verify_highlight.py.']
(ROOT/'summary_ru.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
